css:
.fx-bdg{width:min(760px,100%);display:grid;gap:1.8em;background:color-mix(in srgb,var(--surface) 94%,var(--text));border:1px solid var(--border);border-radius:calc(var(--radius) + 2px);padding:1.6em}
.fx-bdg h3{font-size:1.35em}
.fx-bdg .tb{display:flex;flex-wrap:wrap;gap:1.4em 2em;align-items:center}
.fx-bdg .lab{font-size:.72em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;opacity:.5;display:block;margin-bottom:.8em}
.fx-bdg .ib{position:relative;display:inline-grid;place-items:center;width:3em;height:3em;border-radius:50%;border:1px solid var(--border);background:var(--surface);color:var(--text);cursor:pointer}
.fx-bdg .ib svg{width:1.3em;height:1.3em}.fx-bdg .ib:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-bdg .n{position:absolute;top:-.3em;right:-.3em;min-width:1.5em;height:1.5em;padding:0 .35em;border-radius:99px;background:var(--accent);color:var(--on-accent);font:800 .8em var(--font-body);display:grid;place-items:center;border:2px solid var(--surface)}
.fx-bdg .n::before{content:"";position:absolute;inset:-2px;border-radius:inherit;background:var(--accent);z-index:-1;animation:fxbdgping calc(1.8s/var(--speed)) cubic-bezier(0,0,.2,1) infinite}
.fx-bdg .av{position:relative;width:3em;height:3em;border-radius:50%;display:grid;place-items:center;font:700 .95em var(--font-heading);color:var(--on-primary);background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 50%,var(--accent)))}
.fx-bdg .av.b{background:linear-gradient(135deg,var(--accent),color-mix(in srgb,var(--accent) 50%,var(--primary)));color:var(--on-accent)}
.fx-bdg .av.c{background:color-mix(in srgb,var(--text) 18%,var(--surface));color:var(--text)}
.fx-bdg .st{position:absolute;right:-.05em;bottom:-.05em;width:.95em;height:.95em;border-radius:50%;background:#2eb872;border:2.5px solid var(--bg,color-mix(in srgb,var(--surface) 94%,var(--text)))}
.fx-bdg .st.on::after{content:"";position:absolute;inset:-2.5px;border-radius:50%;border:2px solid #2eb872;animation:fxbdgring calc(2s/var(--speed)) ease-out infinite}
.fx-bdg .st.away{background:var(--accent)}.fx-bdg .st.off{background:color-mix(in srgb,var(--text) 35%,var(--surface))}
.fx-bdg .pill{display:inline-flex;align-items:center;gap:.55em;padding:.45em .95em;border-radius:99px;font:800 .75em var(--font-body);letter-spacing:.1em;text-transform:uppercase;border:1px solid var(--border);background:var(--surface)}
.fx-bdg .dot{position:relative;width:.7em;height:.7em;border-radius:50%;background:var(--accent)}
.fx-bdg .dot::after{content:"";position:absolute;inset:0;border-radius:50%;background:inherit;animation:fxbdgping calc(1.6s/var(--speed)) cubic-bezier(0,0,.2,1) infinite}
.fx-bdg .pill.live{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}.fx-bdg .pill.live .dot{background:var(--on-accent)}
.fx-bdg .new{position:relative;display:inline-block;padding:.3em .7em;border-radius:6px;background:var(--primary);color:var(--on-primary);font:800 .7em var(--font-body);letter-spacing:.1em;text-transform:uppercase;animation:fxbdgglow calc(2.4s/var(--speed)) ease-in-out infinite}
.fx-bdg .menu{display:flex;gap:.5em;flex-wrap:wrap}
.fx-bdg .menu a{display:inline-flex;align-items:center;gap:.6em;padding:.6em 1em;border-radius:var(--radius);border:1px solid var(--border);background:var(--surface);color:var(--text);text-decoration:none;font-weight:600;font-size:.92em}
.fx-bdg .menu a:hover{border-color:var(--primary)}.fx-bdg .menu a:focus-visible{outline:2px solid var(--accent)}
@keyframes fxbdgping{75%,100%{transform:scale(2.1);opacity:0}}
@keyframes fxbdgring{0%{transform:scale(.8);opacity:.9}100%{transform:scale(1.9);opacity:0}}
@keyframes fxbdgglow{50%{box-shadow:0 0 0 .4em color-mix(in srgb,var(--primary) 22%,transparent)}}
@media(prefers-reduced-motion:reduce){.fx-bdg .n::before,.fx-bdg .dot::after,.fx-bdg .st.on::after,.fx-bdg .new{animation:none}.fx-bdg .n::before,.fx-bdg .dot::after{display:none}}

/* touch: :hover mirrored as .is-tap */
.fx-bdg .menu a.is-tap{border-color:var(--primary)}
